import type { IRuntimeTypedPeer } from '@migaia/rpc-process'

type IActionApi = {
  math: { double(value: number): number }; log: { note(value: string): void }
  feed: { count(limit: number): AsyncIterableIterator<number> }; fail: { boom(): void }
}
